using Contoso.Scoring;

namespace Contoso.Scoring.Tests;

[TestClass]
public sealed class ScoreCalculatorTests
{
    private readonly ScoreCalculator _calculator = new();

    // --- CalculatePercentage: boundary & range checks ---

    [TestMethod]
    [DataRow(10, 10, 100.0)]
    [DataRow(0, 10, 0.0)]
    [DataRow(5, 10, 50.0)]
    [DataRow(1, 3, 33.333333333333336)]
    public void CalculatePercentage_ValidInputs_ReturnsExpected(int correct, int total, double expected)
    {
        var result = _calculator.CalculatePercentage(correct, total);

        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    public void CalculatePercentage_AllCorrect_ReturnsExactly100()
    {
        var result = _calculator.CalculatePercentage(20, 20);

        Assert.AreEqual(100.0, result);
    }

    [TestMethod]
    public void CalculatePercentage_PartialScore_IsInValidRange()
    {
        var result = _calculator.CalculatePercentage(7, 10);

        Assert.IsInRange(result, 0.0, 100.0);
        Assert.IsGreaterThan(0.0, result);
        Assert.IsLessThan(100.0, result);
    }

    [TestMethod]
    public void CalculatePercentage_NegativeCorrect_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(-1, 10));
    }

    [TestMethod]
    public void CalculatePercentage_ZeroTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(0, 0));
    }

    [TestMethod]
    public void CalculatePercentage_CorrectExceedsTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(11, 10));
    }

    // --- GetGrade: boundary tests at each grade threshold ---

    [TestMethod]
    [DynamicData(nameof(GradeBoundaryData))]
    public void GetGrade_AtBoundary_ReturnsExpectedGrade(double percentage, string expectedGrade)
    {
        var result = _calculator.GetGrade(percentage);

        Assert.AreEqual(expectedGrade, result);
    }

    public static IEnumerable<(double percentage, string expectedGrade)> GradeBoundaryData =>
    [
        (100.0, "A"),
        (90.0, "A"),   // lower boundary of A
        (89.99, "B"),  // just below A
        (80.0, "B"),   // lower boundary of B
        (79.99, "C"),  // just below B
        (70.0, "C"),   // lower boundary of C
        (69.99, "D"),  // just below C
        (60.0, "D"),   // lower boundary of D
        (59.99, "F"),  // just below D
        (0.0, "F"),
    ];

    // --- NormalizeScore: range assertions ---

    [TestMethod]
    public void NormalizeScore_MidRange_IsInRange()
    {
        var result = _calculator.NormalizeScore(50.0, 100.0);

        Assert.IsInRange(result, 0.0, 100.0);
        Assert.AreEqual(50.0, result);
    }

    [TestMethod]
    public void NormalizeScore_ExceedsMax_CapsAt100()
    {
        var result = _calculator.NormalizeScore(150.0, 100.0);

        Assert.AreEqual(100.0, result);
    }

    [TestMethod]
    public void NormalizeScore_Zero_ReturnsZero()
    {
        var result = _calculator.NormalizeScore(0.0, 100.0);

        Assert.AreEqual(0.0, result);
    }

    [TestMethod]
    public void NormalizeScore_Result_IsAlwaysInValidRange()
    {
        var result = _calculator.NormalizeScore(75.0, 200.0);

        Assert.IsInRange(result, 0.0, 100.0);
        Assert.IsGreaterThan(0.0, result);
    }

    [TestMethod]
    public void NormalizeScore_NegativeRaw_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.NormalizeScore(-1.0, 100.0));
    }

    [TestMethod]
    public void NormalizeScore_ZeroMax_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.NormalizeScore(50.0, 0.0));
    }
}

